    }
    val facts = listOf(
        Fact("venus", "space", "Venus takes longer to rotate once than to orbit the Sun.", "Its rotation takes about 243 Earth days; its orbit takes about 225. A rotation is not the same as sunrise-to-sunrise solar day.", "Earth rotates in roughly one day and orbits in roughly a year. Venus reverses that ordering of durations.", "NASA Science — Venus facts: https://science.nasa.gov/venus/facts/"),
        Fact("moon", "space", "We see nearly the same side of the Moon from Earth.", "The Moon rotates once in approximately the same time it takes to orbit Earth. Small apparent rocking motions let us see somewhat more than half over time.", "Walk around a chair while always facing it: you also rotate as you circle.", "NASA Science — Moon facts: https://science.nasa.gov/moon/facts/"),
        Fact("sunlight", "space", "Sunlight takes about eight minutes to reach Earth.", "Light travels at about 300,000 kilometres per second, and Earth is about 150 million kilometres from the Sun on average.", "Dividing that average distance by light's speed gives about 500 seconds.", "NASA Science — Sun facts: https://science.nasa.gov/sun/facts/"),
